/**
 * The images this backend draws with. They are generated by
 * assets/generate.mjs, committed beside it, and copied by the Roku preset to
 * pkg:/assets/smp/. Every pixel is white, so `blendColor` gives the colour.
 * tests/roku-assets.test.mjs holds each path here to a shipped file.
 */
export const ASSETS = {
  /** Alpha 0 at the left to 1 at the right. */
  rampH: 'pkg:/assets/smp/ramp-h.png',
  /** Alpha 0 at the top to 1 at the bottom. */
  rampV: 'pkg:/assets/smp/ramp-v.png',
  /** Alpha 1 at the centre to 0 at the edge of the inscribed ellipse. */
  rampRadial: 'pkg:/assets/smp/ramp-radial.png',
  /** The bottom-left and bottom-right layers of a four-corner blend. */
  weightBl: 'pkg:/assets/smp/weight-bl.png',
  weightBr: 'pkg:/assets/smp/weight-br.png',
  /** 9-patch shadows of a rounded box, by corner radius and blur. */
  shadow: {
    '0-4': 'pkg:/assets/smp/shadow-r0-b4.9.png',
    '0-8': 'pkg:/assets/smp/shadow-r0-b8.9.png',
    '0-16': 'pkg:/assets/smp/shadow-r0-b16.9.png',
    '0-32': 'pkg:/assets/smp/shadow-r0-b32.9.png',
    '8-4': 'pkg:/assets/smp/shadow-r8-b4.9.png',
    '8-8': 'pkg:/assets/smp/shadow-r8-b8.9.png',
    '8-16': 'pkg:/assets/smp/shadow-r8-b16.9.png',
    '8-32': 'pkg:/assets/smp/shadow-r8-b32.9.png',
    '16-4': 'pkg:/assets/smp/shadow-r16-b4.9.png',
    '16-8': 'pkg:/assets/smp/shadow-r16-b8.9.png',
    '16-16': 'pkg:/assets/smp/shadow-r16-b16.9.png',
    '16-32': 'pkg:/assets/smp/shadow-r16-b32.9.png',
    '32-4': 'pkg:/assets/smp/shadow-r32-b4.9.png',
    '32-8': 'pkg:/assets/smp/shadow-r32-b8.9.png',
    '32-16': 'pkg:/assets/smp/shadow-r32-b16.9.png',
    '32-32': 'pkg:/assets/smp/shadow-r32-b32.9.png',
    '64-4': 'pkg:/assets/smp/shadow-r64-b4.9.png',
    '64-8': 'pkg:/assets/smp/shadow-r64-b8.9.png',
    '64-16': 'pkg:/assets/smp/shadow-r64-b16.9.png',
    '64-32': 'pkg:/assets/smp/shadow-r64-b32.9.png',
  } as Record<string, string>,
} as const;

/** The shadow sizes shipped (assets/generate.mjs writes the same tables). */
export const SHADOW_RADII = [0, 8, 16, 32, 64];
export const SHADOW_BLURS = [4, 8, 16, 32];

function nearest(sizes: number[], value: number): number {
  let best = sizes[0];
  for (let i = 1; i < sizes.length; i++) {
    if (Math.abs(sizes[i] - value) < Math.abs(best - value)) best = sizes[i];
  }
  return best;
}

/** The shipped shadow nearest to a corner radius and blur. */
export function shadowAsset(radius: number, blur: number): { uri: string; radius: number; blur: number } {
  const r = nearest(SHADOW_RADII, radius);
  const b = nearest(SHADOW_BLURS, blur);
  return { uri: ASSETS.shadow[r + '-' + b], radius: r, blur: b };
}
